tool_input.command:
Start-Sleep -Seconds 1
try { $s=Invoke-WebRequest -Uri 'http://127.0.0.1:18098/api/state' -UseBasicParsing -TimeoutSec 25; "state -> $($s.StatusCode) bytes=$($s.Content.Length)"; $j=$s.Content|ConvertFrom-Json; "items=$($j.items.Count) orphans=$($j.orphans.Count) events=$($j.events.Count)"; $j.items | Select-Object -First 5 | ForEach-Object { "  $($_.project)/$($_.env) $($_.port) nginx=$($_.nginx_status) health=$($_.health) be=$($_.backend)" } } catch { "state ERR: $($_.Exception.Message)" }
try { $h=Invoke-WebRequest -Uri 'http://127.0.0.1:18098/' -UseBasicParsing -TimeoutSec 10; "index -> $($h.StatusCode) bytes=$($h.Content.Length)" } catch { "index ERR: $($_.Exception.Message)" }

tool_input.new_string:
    with open(good, 'w') as f:
        f.write('server {
    listen 18888;
}
')
